    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
    if (fullname.getText().isEmpty() || cardnumber.getText().isEmpty() || ccv.getText().isEmpty()) {
        
        JOptionPane.showMessageDialog(null, "Sorry, there is missing data. Please fill in all the options.");
        return; // Stop further execution
    }

    // If all fields are filled, show success message and proceed
    JOptionPane.showMessageDialog(null, "Successfully Pay");
    this.dispose(); // Close the current form
    new MainCustomer().setVisible(true);
    }//GEN-LAST:event_jButton1ActionPerformed

